-- #704 slice 4: the NCAA Division I men's and women's singles championships, college tennis's
-- two knockout draws of 64 players in six rounds, named as the NCAA names them. Men's and women's
-- are separate sport leagues, as in every sport. Idempotent on the (sport_id, name) unique: an
-- admin who already created a league keeps their row, with these round names.
INSERT INTO "sport_leagues" ("id", "sport_id", "name", "bracket_advancement", "round_names", "is_active", "created_at", "updated_at")
SELECT gen_random_uuid(), s."id", league."name", 'FIXED', ARRAY['First Round', 'Second Round', 'Round of 16', 'Quarterfinals', 'Semifinals', 'Final']::text[], TRUE, NOW(), NOW()
FROM "sports" s
CROSS JOIN (VALUES ('NCAA Division I Men'), ('NCAA Division I Women')) AS league("name")
WHERE s."sport" = 'TENNIS'
ON CONFLICT ("sport_id", "name") DO UPDATE SET "round_names" = EXCLUDED."round_names";

-- Each league's contest templates, as the ATP's and the WTA's (`rules/ux-rules.md` §12): one
-- default per format, ahead of its variations, all for a KNOCKOUT of six rounds, doubling to 32 in
-- the final. A 64 draw seeds 16, so it has no Seeds only template, and a six-day event no
-- second-week bracket.
INSERT INTO "contest_config_templates" (
  "id", "sport", "sport_league_id", "event_type", "contest_type", "selection_type", "template_key",
  "name", "description", "sort_order", "is_default", "active", "config_json", "schema_version", "updated_at"
)
SELECT
  gen_random_uuid(), 'TENNIS', l."id", 'KNOCKOUT', preset."contest_type"::"PrismaContestFormat",
  preset."selection_type"::"PrismaSelectionType", preset."template_key", preset."name", preset."description",
  preset."sort_order", preset."is_default", TRUE, preset."config_json"::jsonb, 1, NOW()
FROM (VALUES
  ('NCAA Division I Men', 'TIERED', 'ROSTER', 'ncaa-men-tennis-tiered-doubling', 'Tiered: 1 player per tier, doubling points', 'Pick one player from each of the six tiers, the whole draw. A win scores 1 point in the first round, doubling each round to 32 in the final.', 1, TRUE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
  ('NCAA Division I Men', 'TIERED', 'ROSTER', 'ncaa-men-tennis-tiered-doubling-upset-bonus', 'Tiered: 1 player per tier, doubling + upset bonus', 'Pick one player from each of the six tiers, the whole draw. A win scores 1 point in the first round, doubling each round to 32 in the final, plus the seed difference for an upset.', 2, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
