  ('NCAA Division I Men', 'BUDGET_PICK', 'ROSTER', 'ncaa-men-tennis-budget-doubling', 'Budget: 6 players under the cap, doubling points', 'Every player has a price: pick six whose prices fit under the salary cap. A win scores 1 point in the first round, doubling each round to 32 in the final.', 4, TRUE, '{"selectionType": "BUDGET_PICK", "rosterSize": 6, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
  ('NCAA Division I Men', 'BUDGET_PICK', 'ROSTER', 'ncaa-men-tennis-budget-doubling-upset-bonus', 'Budget: 6 players under the cap, doubling + upset bonus', 'Every player has a price: pick six whose prices fit under the salary cap. A win scores 1 point in the first round, doubling each round to 32 in the final, plus the seed difference for an upset.', 5, FALSE, '{"selectionType": "BUDGET_PICK", "rosterSize": 6, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('NCAA Division I Men', 'RANDOM_DRAW', 'ROSTER', 'ncaa-men-tennis-random-draw-doubling', 'Random draw: 1 player each, doubling points', 'The sweepstake: the draw deals each entry one player at random. A win scores 1 point in the first round, doubling each round to 32 in the final.', 6, TRUE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
  ('NCAA Division I Men', 'RANDOM_DRAW', 'ROSTER', 'ncaa-men-tennis-random-draw-doubling-upset-bonus', 'Random draw: 1 player each, doubling + upset bonus', 'The sweepstake: the draw deals each entry one player at random. A win scores 1 point in the first round, doubling each round to 32 in the final, plus the seed difference for an upset.', 7, FALSE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('NCAA Division I Men', 'BRACKET', 'PREDICTION', 'ncaa-men-tennis-bracket-doubling', 'Bracket: full draw, doubling points', 'Pick the winner of all 63 matches before the first one starts. A right pick scores 1 point in the first round, doubling each round to 32 in the final.', 8, TRUE, '{"selectionType": "BRACKET", "startsAtRound": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
  ('NCAA Division I Men', 'BRACKET', 'PREDICTION', 'ncaa-men-tennis-bracket-doubling-upset-bonus', 'Bracket: full draw, doubling + upset bonus', 'Pick the winner of all 63 matches before the first one starts. A right pick scores 1 point in the first round, doubling each round to 32 in the final, plus the seed difference for an upset.', 9, FALSE, '{"selectionType": "BRACKET", "startsAtRound": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('NCAA Division I Men', 'SURVIVOR', 'PREDICTION', 'ncaa-men-tennis-knockout-survivor', 'Survivor: 1 player a round, each player once', 'Pick one player to win in each round, never the same player twice. A loss puts the entry out; the last ones standing win.', 10, TRUE, '{"selectionType": "SURVIVOR", "maxEntriesPerSquad": 1}'),
