  ('NCAA Division I Women', 'RANDOM_DRAW', 'ROSTER', 'ncaa-women-tennis-random-draw-doubling', 'Random draw: 1 player each, doubling points', 'The sweepstake: the draw deals each entry one player at random. A win scores 1 point in the first round, doubling each round to 32 in the final.', 6, TRUE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
