  ('NCAA Division I Women', 'BRACKET', 'PREDICTION', 'ncaa-women-tennis-bracket-doubling', 'Bracket: full draw, doubling points', 'Pick the winner of all 63 matches before the first one starts. A right pick scores 1 point in the first round, doubling each round to 32 in the final.', 8, TRUE, '{"selectionType": "BRACKET", "startsAtRound": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32], "upsetBonus": {"rule": "NONE"}}}}'),
